diff --git a/src/core/trailers.ts b/src/core/trailers.ts
index fea2056..b1fb8a2 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -2,6 +2,10 @@ import type { Provenance } from "./grade.ts";

 export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
   const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+  // "authored" is self-asserted by the commit's author and cannot be verified without
+  // signature schemes. Until v0.1 has key management, treat any claimed authorship as
+  // unverifiable and demote to "unknown".
+  if (raw === "authored") return "unknown";
+  if (raw === "inherited" || raw === "reconstructed") return raw;
   return "unknown";
 };
